module TopModule (
    input  clk,
    input  x,
    output z
);

    // Internal signals for the three D flip-flops
    reg q0, q1, q2;

    // Assign the complemented outputs for the AND and OR gates
    wire q0_n = ~q0;
    wire q1_n = ~q1;
    wire q2_n = ~q2;

    // D flip-flops with synchronous reset (initialized to zero)
    always @(posedge clk) begin
        // The D input for each flip-flop is the XOR of x and its own current output
        q0 <= q0 ^ x;
        q1 <= q1 ^ x;
        q2 <= q2 ^ x;
    end

    // Three-input NOR gate: output is high only if all inputs are low
    // Inputs: q0 XOR (q0), q1 AND (~q1), q2 OR (~q2)
    // Since A XOR A is always 0, the first input to the NOR is always 0.
    assign z = ~( (q0 ^ q0) & (q1 & q1_n) | (q2 | q2_n) );

endmodule

