        if (L) begin
            q <= {1'b0, r_in};  // Load r_in into the lower two bits; MSB set to 0 (or could be q_in depending on exact intent, but r_in is the load data per spec)
        end else begin
            // Shift right: q[1] goes to Q output position, q[0] gets q_in, q[2] gets XOR of q[1] and q[2]
            // The original full_module logic: q <= {q[1] ^ q[2], q[0], q[2]};
            // Here we map the three bits to the internal state.
            // To match the shift pattern, we assign:
            // new q[2] = q[1] ^ q[2]
            // new q[1] = q[0]
