module TopModule (
    input  clk,
    input  reset,
    input  [7:0] in,
    output reg [23:0] out_bytes,
    output reg done
);

    // State encoding
    typedef enum logic [1:0] {
        IDLE   = 2'b00,
        BYTE1  = 2'b01,
        BYTE2  = 2'b10,
        BYTE3  = 2'b11
    } state_t;

    state_t state, next_state;

    // Shift register to hold the three received bytes
    logic [23:0] shift_reg;

    // Next-state and output logic (combinational)
    always_comb begin
        next_state = state;
        done       = 1'b0;
        out_bytes  = 24'b0;

        case (state)
            IDLE: begin
                // Wait for a byte with bit 3 set (in[3] == 1)
                if (in[3]) begin
                    next_state = BYTE1;
                    shift_reg    = {24'b0, in};  // store first byte in MSBs
                end else begin
                    next_state = IDLE;
                end
            end

            BYTE1: begin
                // Received byte 1, move to byte 2
                next_state = BYTE2;
                shift_reg  = {in, shift_reg[23:8]};  // shift left, insert new byte at LSB
            end

            BYTE2: begin
                // Received byte 2, move to byte 3
                next_state = BYTE3;
                shift_reg  = {in, shift_reg[23:8]};
            end

            BYTE3: begin
                // Received byte 3, complete the message
                next_state = IDLE;
                done       = 1'b1;
                out_bytes  = shift_reg;
            end
        endcase
    end

    // Sequential logic: state register and shift register
    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            state     <= IDLE;
            shift_reg <= 24'b0;
            done      <= 1'b0;
        end else begin
            state     <= next_state;
            shift_reg <= shift_reg;  // updated in combinational logic, captured here
            done      <= done;       // updated in combinational logic, captured here
        end
    end

endmodule

Prob139_2013_q2bfsm.code:
module TopModule (
    input  clk,
    input  resetn,
    input  x,
    input  y,
    output f,
    output g
);

    // State encoding: 3 bits
    // State A: 3'b000
    // State B: 3'b001
    // State C: 3'b010
    // State D: 3'b011
    // State E: 3'b100
    // State F: 3'b101
    // State G: 3'b110
    // State H: 3'b111

    reg [2:0] state, next_state;

    // Output logic (Moore machine: outputs depend only on state)
    assign f = (state == 3'b001);  // f = 1 in state B
    assign g = (state == 3'b110);  // g = 1 in state G

    // State register (positive edge triggered, synchronous active low reset)
    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= 3'b000;  // state A
        end else begin
            state <= next_state;
        end
    end

    // Next-state logic (combinational)
    always @(*) begin
        case (state)
            3'b000: begin // State A: reset asserted or initial
                // As long as reset is asserted, stay in A.
                // When reset is de-asserted, after next clock edge go to B.
                // Since this block is entered after the posedge, if resetn was
                // de-asserted before this edge, we transition to B.
                next_state = 3'b001; // State B
            end
            3'b001: begin // State B: f is 1 for one cycle
                // After this cycle, monitor x for sequence 1,0,1
                next_state = 3'b010; // State C
            end
            3'b010: begin // State C: waiting for x=1 (first of sequence)
                if (x == 1'b1) begin
                    next_state = 3'b011; // State D
                end else begin
                    next_state = 3'b010; // Stay in C
                end
            end
            3'b011: begin // State D: got x=1, now waiting for x=0
                if (x == 1'b0) begin
                    next_state = 3'b100; // State E
                end else begin
                    next_state = 3'b011; // Stay in D
                end
            end
            3'b100: begin // State E: got x=0, now waiting for x=1 (third of sequence)
                if (x == 1'b1) begin
                    next_state = 3'b101; // State F
                end else begin
                    next_state = 3'b100; // Stay in E
                end
            end
            3'b101: begin // State F: sequence 1,0,1 detected, now assert g and monitor y
                // Set g=1 on the following clock cycle (transition to State G)
                next_state = 3'b110; // State G
            end
            3'b110: begin // State G: g=1, monitoring y within at most 2 cycles
                if (y == 1'b1) begin
                    // y became 1 within the cycle, maintain g=1 permanently
                    next_state = 3'b110; // Stay in State G
                end else begin
                    // Check if we have counted one cycle without y=1
                    // Since we are in State G, we need to count up to two cycles.
                    // We transition to a counting state H.
                    next_state = 3'b111; // State H
                end
            end
            3'b111: begin // State H: counted one cycle without y=1, now waiting for second cycle or y=1
                if (y == 1'b1) begin
                    // y became 1 within the second cycle, maintain g=1 permanently
                    next_state = 3'b110; // Go to State G
                end else begin
                    // Two cycles elapsed without y=1, set g=0 permanently
                    next_state = 3'b000; // Go to State A (which has g=0, f=0)
                end
            end
            default: next_state = 3'b000;
        endcase
    end

endmodule

