    input  reset,
    input  [2:0] s,
    output fr2,
    output fr1,
    output fr0,
    output dfr
);

    wire [2:0] s_synced;
    reg  [2:0] s_prev;
    reg  [1:0] level_state; // 00: above s2, 01: between s2 and s1, 10: between s1 and s0, 11: below s0
    reg        dfr_reg;

    // Synchronize inputs
    always @(posedge clk) begin
        if (reset) begin
            s_prev       <= 3'b000;
            level_state  <= 2'b11; // below s0
            dfr_reg      <= 1'b1;
        end else begin
            s_prev       <= s;
            // Determine level state based on current sensors
            if (s[2]) level_state <= 2'b00; // above s2
            else if (s[1]) level_state <= 2'b01; // between s2 and s1
            else if (s[0]) level_state <= 2'b10; // between s1 and s0
            else       level_state <= 2'b11; // below s0

            // dfr logic: increase flow if previous level was lower than current
            // Previous lower means we transitioned from a higher state to a lower state index
            // State 00 (above) -> 01, 10, 11 (down)
            // State 01 -> 10, 11 (down)
            // State 10 -> 11 (down)
            if ((s_prev[2] && !s[2]) || 
                (s_prev[1] && !s[1] && s[0]) || 
                (s_prev[0] && !s[0])) begin
                dfr_reg <= 1'b1;
            end else begin
                dfr_reg <= 1'b0;
            end
        end
    end

    // Output assignments based on level_state and dfr
    assign fr0 = (level_state == 2'b10) || (level_state == 2'b11); // Between s1-s0 or below s0
    assign fr1 = (level_state == 2'b11); // Below s0
    assign fr2 = (level_state == 2'b00); // Above s2 (only if no other, but spec says max below s0, zero above s2)
    // Correction: Above s2 flow is zero. Below s0 is max (fr0, fr1, fr2).
    // Between s2-s1: fr0. Between s1-s0: fr0, fr1.
    // Let's re-evaluate fr2. Spec says: Below s[0]: fr0, fr1, fr2.
    // Between s[1] and s[0]: fr0, fr1.
    // Between s[2] and s[1]: fr0.
    // Above s[2]: None.
    // So fr2 is only asserted when below s0.
    // Let's fix fr2 assignment.
    assign fr2 = (level_state == 2'b11); // Below s0

    // dfr output
    assign dfr = dfr_reg;

    // Active high synchronous reset handling is inside the always block above.
    // The spec says: "resets the state machine to a state equivalent to if the water level had been low for a long time 
    // (no sensors asserted, and all four outputs asserted)."
    // This means on reset: fr0=1, fr1=1, fr2=1, dfr=1.
    // And level_state should be 11 (below s0).
    // The current logic sets level_state <= 2'b11 and dfr_reg <= 1'b1 on reset.
    // fr0, fr1, fr2 assignments happen continuously based on level_state.
    // If level_state is 11, fr0=1, fr1=1, fr2=1. Correct.

endmodule

