module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    // State encoding
    typedef enum logic [3:0] {
        WALK_LEFT,    // 0
        WALK_RIGHT,   // 1
        FALLING,      // 2
        DIGGING,      // 3
        SPLATTERED    // 4
    } state_t;

    state_t state, next_state;

    // Fall duration counter
    typedef logic [5:0] counter_t; // 0 to 63, enough for >20
    counter_t fall_counter, next_fall_counter;

    // Register to remember walking direction before a fall or during dig
    logic [1:0] dir_reg; // 00=walk_left, 01=walk_right, 10=digging left?, 11=unused
    // Actually, we only need 0 for left, 1 for right. Let's use 1 bit.
    logic       walk_dir; // 0 = left, 1 = right. Tracks direction when walking.

    // Outputs (Moore machine - outputs depend only on state)
    assign walk_left   = (state == WALK_LEFT);
    assign walk_right  = (state == WALK_RIGHT);
    assign aaah        = (state == FALLING);
    assign digging     = (state == DIGGING);

    // State register (positive edge triggered, async reset)
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            state       <= WALK_LEFT;
            fall_counter <= 0;
            walk_dir    <= 0; // default to left
        end else begin
            state       <= next_state;
            fall_counter <= next_fall_counter;
            // Update walk_dir when walking left or right
            // We update it in the combinational logic below, but for the register
            // we need to capture it. Actually, we can update walk_dir in the
            // always_ff block based on the new state, or in always_comb and
            // feed it back. Let's update it in the always_ff block for simplicity
            // in tracking the "before fall" direction.
            // However, the spec says "resume walking in the same direction as
            // before the fall". If we fall from WALK_LEFT, walk_dir should be 0.
            // If we fall from WALK_RIGHT, walk_dir should be 1.
            // We can set walk_dir when transitioning from WALK_LEFT/RIGHT to FALLING/DIGGING.
            // But the always_ff updates on the new state. Let's just update walk_dir
            // whenever we are in WALK_LEFT or WALK_RIGHT state.
            // Actually, it's easier to update walk_dir in the always_comb and assign
            // it to a wire, then capture it in always_ff. But let's keep it simple:
            // We will update walk_dir in the always_ff block based on the state
            // we are leaving or entering.
            // Let's just use a simple rule: walk_dir is 0 if we were walking left,
            // 1 if right. We'll update it when we transition to FALLING or DIGGING
            // from a walking state, and keep it when in FALLING/DIGGING.
            // For now, we'll update it in the always_ff block.
            // Actually, the standard way is to have the register update based on
            // the current state and inputs. Let's just update walk_dir here:
            // if state is WALK_LEFT, walk_dir <= 0; if WALK_RIGHT, walk_dir <= 1;
            // This way, walk_dir always reflects the current walking direction
            // if walking, or the last walking direction if not walking.
            // But wait, if we are in FALLING, we want to remember the direction
            // we fell from. If we just do `if (state == WALK_LEFT) walk_dir <= 0;`
            // then when we are in FALLING, walk_dir might have been overwritten
            // if we started walking again? No, if we are in FALLING, state != WALK_LEFT.
            // So this works: walk_dir retains the value from the last cycle we were
            // in WALK_LEFT/RIGHT. If we never walk, it stays at reset value (0).
            // This is actually perfect for our needs.
            if (state == WALK_LEFT)
                walk_dir <= 0;
            else if (state == WALK_RIGHT)
                walk_dir <= 1;
            // else (FALLING, DIGGING, SPLATTERED) walk_dir retains previous value
        end
    end

    // Next-state logic
    always_comb begin
        // Default: stay in current state
        next_state = state;
        next_fall_counter = fall_counter;

        case (state)
            WALK_LEFT: begin
                // Priority: fall > dig > switch direction
                if (!ground) begin
                    // Fall immediately when ground disappears
                    next_state = FALLING;
                    next_fall_counter = 1;
                    // walk_dir will be updated in always_ff based on new state (FALLING),
                    // but since state is now FALLING, the always_ff block's
                    // "if (state == WALK_LEFT)" won't trigger. We need to ensure
                    // walk_dir remembers the left direction. 
                    // Since we are transitioning FROM WALK_LEFT, we should set walk_dir <= 0 here,
                    // or rely on the always_ff block. The always_ff block currently sets
                    // walk_dir based on the *new* state. If new state is FALLING,
                    // neither WALK_LEFT nor WALK_RIGHT condition triggers, so walk_dir
                    // keeps its old value. Since old value was 0 (from previous cycle
                    // being WALK_LEFT), this works! But what if we were in WALK_RIGHT
                    // and switched to WALK_LEFT, then fell? walk_dir would be 0. Good.
                    // What if we fall from WALK_RIGHT? walk_dir is 1, good.
                end else if (dig) begin
                    // Start digging when walking on ground
                    next_state = DIGGING;
                    // walk_dir retains value. If we were walking left, walk_dir is 0.
                end else if (bump_left || bump_right) begin
                    // Switch direction when bumped
                    if (bump_left && !bump_right)
                        next_state = WALK_RIGHT;
                    else if (bump_right && !bump_left)
                        next_state = WALK_LEFT;
                    else
                        // Bumped on both sides - still switch
                        next_state = (state == WALK_LEFT) ? WALK_RIGHT : WALK_LEFT;
                    // walk_dir will be updated in always_ff based on new state.
                end
                // else stay WALK_LEFT
            end

            WALK_RIGHT: begin
                if (!ground) begin
                    next_state = FALLING;
                    next_fall_counter = 1;
                end else if (dig) begin
                    next_state = DIGGING;
                end else if (bump_left || bump_right) begin
                    if (bump_left && !bump_right)
                        next_state = WALK_LEFT;
                    else if (bump_right && !bump_left)
                        next_state = WALK_RIGHT;
                    else
                        next_state = (state == WALK_LEFT) ? WALK_RIGHT : WALK_LEFT;
                end
            end

            FALLING: begin
                // Count falling cycles
                if (fall_counter >= 20) begin
                    // Already fell for >= 20 cycles
                    if (ground) begin
                        // Ground reappeared after long fall -> splatter
                        next_state = SPLATTERED;
                        next_fall_counter = 0;
                    end else begin
                        // Still falling, keep counting (should not happen if counter >= 20,
                        // but just in case of wrap or logic, keep counting or saturate)
                        // Spec says "if a Lemming falls for more than 20 clock cycles then hits the ground"
                        // So if counter is already >= 20 and ground is 0, it's still falling.
                        // We keep counting (or saturate at 63). Let's keep incrementing.
                        next_fall_counter = fall_counter + 1; // saturate at 63 implicitly if needed, but 5:0 max 63.
                        // Actually, if fall_counter is 20 (binary 010100), +1 = 21... up to 63.
                        // If it reaches 63, it stays 63. But spec says >20 triggers splatter on hit.
                        // We just need to know if it's >= 20. So incrementing is fine.
                    end
                end else begin
                    // Fall duration < 20 cycles
                    if (ground) begin
                        // Ground reappeared within 20 cycles -> resume walking
                        // in the same direction as before the fall.
                        // walk_dir remembers the direction we fell from.
                        if (walk_dir == 0) begin
                            next_state = WALK_LEFT;
                        end else begin
                            next_state = WALK_RIGHT;
                        end
                        next_fall_counter = 0;
                    end else begin
                        // Still falling, increment counter
                        next_fall_counter = fall_counter + 1;
                    end
                end
            end

            DIGGING: begin
                if (!ground) begin
                    // Reached other side while digging - fall
                    next_state = FALLING;
                    next_fall_counter = 1;
                    // walk_dir retains the direction we were digging.
                    // Since we were walking on ground before digging, walk_dir
                    // holds that direction. When we fall from DIGGING, we need
                    // to remember that direction. The always_ff block will update
                    // walk_dir based on the new state FALLING? No, FALLING doesn't
                    // update walk_dir (only WALK_LEFT/RIGHT do). So walk_dir keeps
                    // the value from before we started digging. This is correct:
                    // if we were walking left and dug, walk_dir is 0. When we fall,
                    // walk_dir remains 0, and on ground reappearance, we resume left.
                end else if (bump_left || bump_right) begin
                    // Being bumped while digging has no effect
                    // stay DIGGING
                end else begin
                    // Continue digging on ground
                    next_state = DIGGING;
                end
            end

            SPLATTERED: begin
                // Forever stuck - do nothing
                next_state = SPLATTERED;
                next_fall_counter = 0;
            end
        endcase
    end

endmodule
